tool.parameters:
{
  "path": { "type": "string", "description": "要编辑的文件绝对路径" },
  "old_string": { "type": "string", "description": "要搜索的原始文本（必须唯一匹配）" },
  "new_string": { "type": "string", "description": "替换后的新文本" }
}

{
  "path": { "type": "string", "description": "要写入的文件绝对路径" },
  "content": { "type": "string", "description": "文件的完整内容" }
}

{
  "pattern": { "type": "string", "description": "Glob 匹配模式，例如 '*.js', 'src/**/*.ts'" },
  "path": { "type": "string?", "description": "可选的基础目录路径" }
}

{
  "pattern": { "type": "string", "description": "正则表达式模式" },
  "path": { "type": "string?", "description": "可选的文件或目录路径" },
  "type": { "type": "string?", "description": "文件类型过滤，如 'js', 'ts', 'py', 'rust'" },
  "-C": { "type": "number?", "description": "显示匹配行前后的上下文行数" },
  "output_mode": { "type": "string?", "description": "输出模式：'content'(默认), 'files_with_matches', 'count'" }
}

tool.usage_notes:
- 使用 output_mode='files_with_matches' 只获取包含匹配的文件列表
- 特殊字符需要转义：interface\{\} 匹配 interface{}
- 跨行模式需要设置 multiline: true

